"""Phase 12D markdown report."""


def render_phase12d_report_md(result):
    lines = []
    a = lines.append
    a("# Phase 12D report — resolve the local-periodicity step limit; ingest the real HFSS data")
    a("")
    a(
        "Generated by `scripts/research/run_phase12d.py` / `src/phase12d/run.py`. No ML anywhere in this "
        "phase: every number is a direct MoM solve through the unmodified `solver.assemble_system`/"
        "`solve` pipeline, a closed-form Floquet-order power decomposition of a real solved current "
        "(`phase12d/floquet_power.py`), or real HFSS Touchstone data (`phase9/hfss_reference.py`'s "
        "new `read_touchstone`)."
    )
    a("")
    a("## 1. Final statuses")
    a("")
    a("```")
    a(f"Task A (step-size curve):  {result.task_a_gate.status}")
    a(f"  {result.task_a_gate.reason}")
    a(f"Task B (aperture test):    {result.task_b_gate.status}")
    a(f"  {result.task_b_gate.reason}")
    a(f"Task C (HFSS ingestion):   {result.task_c_gate.status}")
    a(f"  {result.task_c_gate.reason}")
    a("Geometry inversion:  GEOMETRY_INVERSION_LOCKED")
    a("STEP export:         STEP_EXPORT_LOCKED")
    a("```")
    a("")

    a("## 2. Task A: the step-size curve")
    a("")
    a("Reference reflection-phase curve (S11_xx, aligned mesh):")
    a("")
    a("| L [mm] | \\|S11\\| | phase [deg] |")
    a("|---|---|---|")
    for c in result.curve:
        a(f"| {c.l_mm:.4f} | {c.s11_mag:.6f} | {c.s11_phase_deg:.2f} |")
    a("")
    ctr = result.centers
    a(
        f"Centres: off-resonance L={ctr.off_resonance.l_mm:.4f} mm, "
        f"near-resonance L={ctr.near_resonance.l_mm:.4f} mm, at-resonance L={ctr.at_resonance.l_mm:.4f} mm."
    )
    a("")
    a(
        "| case | kind | achieved step [deg] | reflection phase error [deg] | reflection magnitude error [dB] | dipole relative error (Phase 9 metric) |"
    )
    a("|---|---|---|---|---|---|")
    for c in result.step_cases:
        a(
            f"| {c.name} | {c.kind} | {c.achieved_step_deg:.2f} | {c.reflection_phase_error_deg:.3f} | "
            f"{c.reflection_magnitude_error_db:.4f} | {c.dipole_relative_complex_error:.4f} |"
        )
    a("")

    a("## 3. Task B: aperture-level Floquet-order power test")
    a("")
    if result.aperture_results:
        a(
            "| N cells | achieved span [deg] | n_unknowns | runtime [s] | intended order | fraction in intended | fraction specular | total propagating |"
        )
        a("|---|---|---|---|---|---|---|---|")
        for r in result.aperture_results:
            a(
                f"| {r.n_cells} | {r.achieved_span_deg:.1f} | {r.n_unknowns} | {r.runtime_s:.1f} | "
                f"{r.intended_order} | {r.fraction_intended:.4f} | {r.fraction_specular:.4f} | "
                f"{r.total_propagating_fraction:.4f} |"
            )
        a("")
        attempted_ns = {r.n_cells for r in result.aperture_results}
        infeasible = [n for n in result.aperture_requested_sizes if n not in attempted_ns]
        if infeasible:
            a(
                f"**Infeasible within this phase's practical budget: N = {infeasible}** (attempted; "
                f"see the cost note in `src/phase12d/aperture_test.py`'s module docstring)."
            )
            a("")
    else:
        a("No requested aperture size completed within budget.")
        a("")

    a("## 4. Task C: real HFSS data ingestion")
    a("")
    a("Provenance (recorded exactly as given, never invented):")
    a("")
    for k, v in result.hfss_provenance.items():
        a(f"- **{k}**: {v}")
    a("")
    if result.hfss_comparisons:
        a(
            "| case | L [mm] | mean dphase (mode1) [deg] | max \\|dphase\\| [deg] | max dmag [dB] | max cross-pol | meets tolerance |"
        )
        a("|---|---|---|---|---|---|---|")
        for c in result.hfss_comparisons:
            a(
                f"| {c.case_id} | {c.l_mm} | {c.mean_dphase_deg:.3f} | {c.max_abs_dphase_deg:.3f} | "
                f"{c.max_dmag_db:.5f} | {c.max_crosspol_mag:.2e} | {c.meets_tolerance} |"
            )
        a("")
    a(
        "Geometric identity, Phase 12C's own earlier single-cell STEP exports vs the ones actually "
        "sent to/from HFSS (`hfss_exports/phase12_grounded_8mm/`):"
    )
    a("")
    if result.geometric_identity:
        a("| case | metal volume relative diff | bounding box matches | identical |")
        a("|---|---|---|---|")
        for g in result.geometric_identity:
            a(f"| {g.case_id} | {g.metal_volume_relative_diff:.2e} | {g.metal_bbox_matches} | {g.identical} |")
    else:
        a("(cadquery not available in this environment; check skipped.)")
    a("")

    a("## 5. Recommendation for Phase 13's forward model")
    a("")
    a(result.recommendation)
    a("")

    a("## 6. Rules followed")
    a("")
    a(
        "Measured numbers only; no HFSS data fabricated or extrapolated (Task C's provenance and "
        "tolerance were fixed before looking at the comparison numbers). Earlier phases' code and "
        "results are untouched (`phase12c.locality_study.build_periodic_phase_gradient_supercell`/"
        "`build_1d_row_grid`/`build_2d_gradient_grid`/`classify_centers` are reused unmodified; "
        "outputs are written only under `results/phase12d_*`). No ML/fitted surrogate appears "
        "anywhere in this phase."
    )
    return "\n".join(lines) + "\n"
